function comb(r) {
	var c = [];
	c[0] = -1;
	var k = 1;
	c[1] = 0;
	var ret = [];

	while (k != 0) {
		for (var i = k + 1; i <= r; i++) {
			c[i] = c[i - 1] + 1;
		}

		var arr = []
		for (var i = 1; i <= r; i++) {
			arr.push(c[i]);
		}
		ret.push(arr);

		k = r;
		while (c[k] == 9 - r + k)
			k = k - 1;

		c[k] = c[k] + 1;
	}

	return ret;
}

